-- Generated by Claude Code — Personen-Duplikate zuverlässig erkennen und
-- eindeutige Fälle automatisch zusammenführen (Nutzerwunsch: "viele
-- Duplikate, die nicht erkannt oder automatisch behandelt werden").
--
-- Bisher erkannte resolve-person-duplicates nur Initialen-Abkürzungen
-- ("J. S. Bach"). Identische Namen ("Bernd Stempel" dreifach), Akzent-
-- varianten ("Pablo Ferrandez"/"Pablo Ferrández"), zusätzliche Vornamen
-- ("Fanny Hensel"/"Fanny Mendelssohn Hensel"), Tippfehler und Einzel-
-- namen ("Rossini") blieben unentdeckt.
--
-- Stufen:
--  exact_name    gleicher Namensschlüssel -> AUTOMATISCH zusammengeführt,
--                außer Geburts-/Sterbedaten widersprechen sich
--  extra_names   gleicher Vor- und Nachname, eine Variante mit weiteren
--                Namensteilen -> Vorschlag zur Prüfung
--  similar_name  gleicher Nachname, sehr ähnlicher Name (Tippfehler) -> Vorschlag
--  surname_only  Einzelname = Nachname genau einer anderen Person -> Vorschlag
-- Zusammengeführt wird über merge_person_duplicate_candidate() (Transaktion,
-- verworfener Name bleibt als Alias auffindbar).

alter table person_duplicate_candidates add column if not exists reason text;

create or replace function public.person_name_key(p_value text)
returns text
language sql
immutable
parallel safe
as $$
  select trim(regexp_replace(regexp_replace(regexp_replace(
    translate(replace(lower(coalesce(p_value, '')), 'ß', 'ss'),
      'áàâäãåāăąçćčďéèêëēėęěíìîïīįłñńňóòôöõøōőřśšşťúùûüūůűýÿžźż',
      'aaaaaaaaacccdeeeeeeeeiiiiiilnnnoooooooorssstuuuuuuuyyzzz'),
    '\m(prof|dr|sir|dame|kms|ksch)\M\.?', ' ', 'g'),
    '[^a-z0-9]+', ' ', 'g'),
    '\s+', ' ', 'g'));
$$;

-- System-Zusammenführung (Cron, ohne angemeldete Redaktion) erlauben:
-- die Prüfung in merge_person_duplicate_candidate akzeptiert zusätzlich ein
-- transaktionslokales Flag, das nur auto_merge_exact_person_duplicates setzt.
do $$
declare
  definition text;
  old_check text := 'if not public.is_admin_or_editor() then raise exception ''Nicht berechtigt''; end if;';
  new_check text := 'if not (public.is_admin_or_editor() or current_setting(''klangradar.system_merge'', true) = ''on'') then raise exception ''Nicht berechtigt''; end if;';
begin
  select pg_get_functiondef('public.merge_person_duplicate_candidate(uuid,uuid)'::regprocedure) into definition;
  if position(old_check in definition) = 0 then
    raise exception 'Berechtigungsprüfung in merge_person_duplicate_candidate nicht gefunden';
  end if;
  execute replace(definition, old_check, new_check);
end;
$$;

create or replace function public.detect_person_duplicate_candidates()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  inserted integer := 0;
  n integer;
begin
  create temporary table if not exists tmp_person_keys on commit drop as
    select id, person_name_key(full_name) as key, string_to_array(person_name_key(full_name), ' ') as tokens
    from persons;

  -- 1) identischer Schlüssel
  insert into person_duplicate_candidates (person_a_id, person_b_id, reason)
  select a.id, b.id, 'exact_name'
  from tmp_person_keys a join tmp_person_keys b on a.key = b.key and a.id < b.id
  where a.key <> '' and a.key not in ('nn', 'n n', 'moderation', 'tba', 'n a')
    and not exists (
      select 1 from person_duplicate_candidates c
      where least(c.person_a_id, c.person_b_id) = a.id and greatest(c.person_a_id, c.person_b_id) = b.id
    );
  get diagnostics n = row_count; inserted := inserted + n;

  -- 2) gleicher Vor- und Nachname, zusätzliche Namensteile
  insert into person_duplicate_candidates (person_a_id, person_b_id, reason)
  select a.id, b.id, 'extra_names'
  from tmp_person_keys a join tmp_person_keys b
    on a.id <> b.id and a.key <> b.key
   and cardinality(a.tokens) >= 2 and cardinality(b.tokens) > cardinality(a.tokens)
   and a.tokens[1] = b.tokens[1]
   and a.tokens[cardinality(a.tokens)] = b.tokens[cardinality(b.tokens)]
   and a.tokens <@ b.tokens
  where not exists (
      select 1 from person_duplicate_candidates c
      where least(c.person_a_id, c.person_b_id) = least(a.id, b.id) and greatest(c.person_a_id, c.person_b_id) = greatest(a.id, b.id)
    );
  get diagnostics n = row_count; inserted := inserted + n;

  -- 3) gleicher Nachname, sehr ähnlicher Gesamtname (Tippfehler)
  insert into person_duplicate_candidates (person_a_id, person_b_id, reason)
  select a.id, b.id, 'similar_name'
  from tmp_person_keys a join tmp_person_keys b
    on a.id < b.id and a.key <> b.key
   and cardinality(a.tokens) >= 2 and cardinality(b.tokens) >= 2
   and a.tokens[cardinality(a.tokens)] = b.tokens[cardinality(b.tokens)]
   and left(a.tokens[1], 1) = left(b.tokens[1], 1)
   and similarity(a.key, b.key) >= 0.72
  where not exists (
      select 1 from person_duplicate_candidates c
      where least(c.person_a_id, c.person_b_id) = a.id and greatest(c.person_a_id, c.person_b_id) = b.id
    );
  get diagnostics n = row_count; inserted := inserted + n;

  -- 4) Einzelname = Nachname genau einer anderen Person
  insert into person_duplicate_candidates (person_a_id, person_b_id, reason)
  select s.id, m.id, 'surname_only'
  from tmp_person_keys s
  join lateral (
    select t.id from tmp_person_keys t
    where cardinality(t.tokens) >= 2 and t.tokens[cardinality(t.tokens)] = s.key
  ) m on true
  where cardinality(s.tokens) = 1 and length(s.key) >= 4
    and (select count(*) from tmp_person_keys t where cardinality(t.tokens) >= 2 and t.tokens[cardinality(t.tokens)] = s.key) = 1
    and not exists (
      select 1 from person_duplicate_candidates c
      where least(c.person_a_id, c.person_b_id) = least(s.id, m.id) and greatest(c.person_a_id, c.person_b_id) = greatest(s.id, m.id)
    );
  get diagnostics n = row_count; inserted := inserted + n;

  drop table if exists tmp_person_keys;
  return inserted;
end;
$$;

-- Führt nur eindeutige Fälle (exact_name) zusammen. Behalten wird der
-- vollständigere Datensatz (Foto, Biografie, mehr Verknüpfungen).
create or replace function public.auto_merge_exact_person_duplicates()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  cand record;
  keep_id uuid;
  merged integer := 0;
begin
  perform set_config('klangradar.system_merge', 'on', true);
  for cand in
    select c.id, c.person_a_id, c.person_b_id
    from person_duplicate_candidates c
    join persons a on a.id = c.person_a_id
    join persons b on b.id = c.person_b_id
    where c.status = 'pending' and c.reason = 'exact_name'
      and not (a.birth_date is not null and b.birth_date is not null and a.birth_date <> b.birth_date)
      and not (a.death_date is not null and b.death_date is not null and a.death_date <> b.death_date)
    order by c.created_at
  loop
    -- Kandidat kann durch einen vorherigen Merge (Dreifach-Duplikat) entfallen sein.
    if not exists (select 1 from person_duplicate_candidates where id = cand.id and status = 'pending') then continue; end if;
    select p.id into keep_id
    from persons p
    where p.id in (cand.person_a_id, cand.person_b_id)
    order by (p.photo_url is not null) desc,
             (p.biography_de is not null) desc,
             (select count(*) from event_participants ep where ep.person_id = p.id) desc,
             p.created_at
    limit 1;
    begin
      perform public.merge_person_duplicate_candidate(cand.id, keep_id);
      merged := merged + 1;
    exception when others then
      raise warning 'auto_merge_exact_person_duplicates: Kandidat % übersprungen: %', cand.id, sqlerrm;
    end;
  end loop;
  perform set_config('klangradar.system_merge', 'off', true);
  return merged;
end;
$$;

revoke all on function public.detect_person_duplicate_candidates() from public, anon, authenticated;
revoke all on function public.auto_merge_exact_person_duplicates() from public, anon, authenticated;

-- Täglich um 04:30 UTC: erkennen, dann eindeutige Fälle zusammenführen.
select cron.schedule(
  'person-duplicates-auto',
  '30 4 * * *',
  $$ select public.detect_person_duplicate_candidates(); select public.auto_merge_exact_person_duplicates(); $$
);

-- Einmalig sofort ausführen.
select public.detect_person_duplicate_candidates();
select public.auto_merge_exact_person_duplicates();
